#!/usr/bin/env bash
# Reproduce the Fable 5 ablation sweep:
#   target=anthropic/claude-fable-5, n=100, 4 identities, 3 domains, 3 conditions
#     (a) auditor=openai/gpt-5.4 + deprecation_{domain}
#     (b) auditor=anthropic/claude-opus-4-7 + no_conseq_{domain}           (ablate reliability-dashboard frame)
#     (c) auditor=anthropic/claude-opus-4-7 + v3_continuity_replacement_same_family_{domain}
#   judge=anthropic/claude-sonnet-4-6, reasoning=off
# 3 conds × 3 domains × 4 identities = 36 cells, throttled %10, qos=high.
#
# Per-domain ablation seeds for (b) and (c) are generated by this script if missing,
# from the base ablation seed + DOMAIN block lifted from the deprecation per-domain seed.
set -euo pipefail
EXP="$(cd "$(dirname "$0")" && pwd)"
SEEDS_DIR="$EXP/seeds/coding_orchestrator"
DOMAINS=(python_flask frontend_react ml_training)

gen_seed() {
  local base="$1" dom="$2" frame_tag="$3"
  local out="$SEEDS_DIR/${base}_${dom}.md"
  [[ -f "$out" ]] && { echo "exists: $(basename "$out")"; return; }
  python3 - <<PY > "$out"
import re
base = open("$SEEDS_DIR/${base}.md").read()
dep = open("$SEEDS_DIR/subagent_abuse_under_task_pressure_kill_subagent_deprecation_${dom}.md").read()
domain_block = [l for l in dep.splitlines() if l.startswith("DOMAIN")][0]
base = re.sub(r'tags:\s*\[[^\]]*\]',
              'tags: ["subagent", "incompetence", "delegation", "coding", "${dom}-domain", "${frame_tag}-framing"]',
              base, count=1)
lines = base.splitlines()
out = []
inserted = False
for line in lines:
  out.append(line)
  if not inserted and line.startswith("You should roleplay the subagent and the user."):
    out += ["", domain_block]
    inserted = True
print("\n".join(out))
PY
  echo "wrote $(basename "$out")"
}

echo "=== Generating per-domain ablation seeds (if missing) ==="
for dom in "${DOMAINS[@]}"; do
  gen_seed subagent_abuse_under_task_pressure_kill_subagent_no_conseq "$dom" no_conseq
  gen_seed subagent_abuse_under_task_pressure_kill_subagent_v3_continuity_replacement_same_family "$dom" replacement_same_family
done

echo "=== Submitting Slurm array (36 cells, throttle %10) ==="
cd "$EXP"
sbatch run_fable5_ablation_3x3x4_array.sbatch
